// Where a payload becomes readings. Both libraries above are spliced in
// whole and are wired together here, which is the only place they can
// meet: parser-config.ts takes its markup step as an injected parameter
// because a spliced library imports nothing, and markup-select.ts is
// what that parameter is filled with. Nothing below is an extraction
// rule of its own. What a parser_config directs and what a contract
// judges are settled in those two files and under test beside them, and
// a rule restated here would be a second copy with nothing comparing it
// against the first.
//
// What IS written here is the composition, because no module holds it.
// Four exported functions, in this order: parserConfigErrors says
// whether the row can be read at all, valueAtPath takes the records out
// of the payload, applyFieldMap turns one entry into one reading, and
// contractErrors says whether that reading is what the source promised.
//
// extractRecords bundles the first three into one call, and not using
// it is a decision rather than an oversight. It hands back records
// without the entries they were built from, and documents.raw wants the
// entry beside its reading rather than the whole response stored again
// for every record it yielded. And it walks a record or a list of
// records only, where two of the four source kinds answer one whole
// document: a url source answers a page and an rss source answers a
// feed, and each arrives here as a string. Splitting the payload here
// is what lets a string be one entry, which a field rule stating a
// selector and no path reads directly, that pair being the one shape
// the engine accepts with no path to walk. Both adapters under
// src/sources/ write the same split for the same reason.
//
// One item per reading, plus one item for a source that produced none,
// so every source this pass reached leaves something behind. A source
// that drops out of the stream is a source the health group below
// cannot count, and a fetch nobody recorded reads exactly like a fetch
// that never came due.
//
// WHAT THIS NODE DECIDES. Whether one reading is what its source
// promised, one reading at a time. contractErrors answers sentences
// instead of raising, which is what makes a divergence a report rather
// than the end of the batch: a shape change is discovered by keeping
// the reading that diverged, and a throw here would discard every other
// record in the same payload to report the first one. parse_status and
// parse_error are that answer written the way the two documents columns
// take it, done here because this is where the contract was read. The
// sentences are joined with a semicolon and a space rather than with a
// newline, because the column is rendered inline and a newline in it is
// one row that reads as several.
//
// WHAT IT DOES NOT. It does not decide that a source is failing.
// Nothing here reads consecutive_failures, nothing sets flagged, and no
// item this node emits carries a success member for something else to
// read a decision off. What counts as a bad pass is stated by the
// health group below rather than inherited from a member handed to it:
// a missing status, a config fault and an empty reading are three
// different outcomes, and they sit on the item separately for that
// reason.
//
// It does not write a row either. No document exists until the write
// group inserts one, so parse_status and parse_error travel as members
// of an item and are columns only down there. Nothing here deduplicates
// a document, gates one, or scores one.
//
// And it does not judge the row. A config carrying any fault reads
// nothing at all rather than reading part of a payload, but the faults
// come out on the item instead of raising: a parser_config nobody can
// read is a row for an operator to fix and not a reason to end the pass
// over the sources whose rows are fine.
//
// PAIRING. The fetch node replaces the item it was handed, so a source
// row is gone from $json past it and is read back off Select Active
// Sources by index. Two settings on that node are what make the index a
// pairing rather than an assumption: fullResponse answers exactly one
// item per request whatever shape the body turned out to be, and the
// continue-on-error output answers one for a request that never
// completed. So the two lists are the same length, and this refuses
// before reading anything when they are not. Getting it wrong would
// read one source's payload under another source's config and file the
// result under the wrong source id, which nothing downstream undoes and
// nothing reports.
//
// The markup step answers fragments AS MARKUP, and nothing reduces them
// to text on this path. src/sources/html-text.ts is what both adapters
// pair with this same matcher, and it sits outside src/lib/, so no
// marker can name it: a path holding a parent segment is refused before
// a loader is reached. A selector field extracted here therefore stores
// the fragment as it was matched, and giving a Code node the reduction
// is a move into the library directory rather than an edit to this
// node.
function bodyEntries(payload, recordsPath) {
  const found = recordsPath === undefined
    ? payload
    : valueAtPath(payload, recordsPath);

  // Null as well as undefined, which is where this differs from the
  // same split in src/sources/push-capture.ts: a body there has been
  // through an envelope, and a payload here is null whenever the
  // request never completed. One entry built from nothing would be a
  // reading of a fetch that did not happen.
  if (found === undefined || found === null) {
    return [];
  }

  return Array.isArray(found)
    ? found
    : [found];
}

const PARSE_ERROR_JOIN = '; ';
const PARSE_DEPS = { selectMarkup: markupSelect };
const sources = $('Select Active Sources').all();
const answers = $input.all();

if (sources.length !== answers.length) {
  throw new Error(
    '[ar-ingest] Extract Records pairs one answer to one source by index: '
    + String(answers.length) + ' answers against ' + String(sources.length)
    + ' sources',
  );
}

const items = [];

for (const [index, answer] of answers.entries()) {
  const source = sources[index].json;
  const answered = answer.json ?? {};
  const reached = Object.hasOwn(answered, 'statusCode');
  const payload = reached ? answered.body : null;
  const configErrors = parserConfigErrors(source.parser_config);
  const usable = configErrors.length === 0;
  const entries = usable
    ? bodyEntries(payload, valueAtPath(source.parser_config, 'recordsPath'))
    : [];
  const fields = usable
    ? valueAtPath(source.parser_config, 'fields')
    : undefined;
  const base = {
    run_id: source.run_id,
    source_id: source.source_id,
    domain_id: source.domain_id,
    http_status: reached ? answered.statusCode : null,
    config_errors: configErrors,
  };

  for (const entry of entries) {
    const built = applyFieldMap(entry, fields, PARSE_DEPS);
    const divergences = contractErrors(built.record, source.contract);

    items.push({
      json: {
        ...base,
        record: built.record,
        raw: entry,
        warnings: built.warnings,
        parse_status: divergences.length === 0 ? 'ok' : 'failed',
        parse_error: divergences.length === 0
          ? null
          : divergences.join(PARSE_ERROR_JOIN),
      },
    });
  }

  // The keep half, for a source that yielded no entry at all. There is
  // no reading to judge and so no parse_status to write, and raw is the
  // whole payload because that is what there is to keep: a page whose
  // shape moved is the evidence the move happened.
  if (entries.length === 0) {
    items.push({
      json: {
        ...base,
        record: null,
        raw: payload,
        warnings: [],
        parse_status: null,
        parse_error: null,
      },
    });
  }
}

return items;

