    if (required !== undefined && typeof required !== 'boolean') {
      throw new Error(site + 'states a required that is not a boolean');
    }

    return { name, type, required: required === true };
  });
}

// The text an answer carried, or the one fault that ended the reading.
// Read in the order the members actually arrive in: a completed call
// answers text, and a call that did not complete answers an error
// member instead, Extract Finding Fields declaring onError
// continueRegularOutput so that a failure is still an item and the
// position below it still lines up.
function answerText(answer) {
  const text = ownValue(answer, 'text');

  if (typeof text !== 'string') {
    return {
      text: '',
      fault: Object.hasOwn(answer, 'error')
        ? ANSWER_FAULTS.noAnswer
        : ANSWER_FAULTS.notText,
    };
  }

  return text.length > MAX_ANSWER_CHARS
    ? { text: '', fault: ANSWER_FAULTS.tooLong }
    : { text, fault: '' };
}

// The answer with its fence taken off, where it wore one. The opening
// line goes whole, that line carrying the language a model names its
// own answer with, and everything from the last fence on goes with it.
// A fence with no line break after it and a fence never closed are both
// left as they stand: neither is a shape this can repair, and the parse
// below reports it.
function unfenced(text) {
  const trimmed = text.trim();

  if (!trimmed.startsWith(ANSWER_FENCE)) {
    return trimmed;
  }

  const opened = trimmed.indexOf('\n');
  const closed = trimmed.lastIndexOf(ANSWER_FENCE);

  if (opened === -1) {
    return trimmed;
  }

  return closed > opened
    ? trimmed.slice(opened + 1, closed).trim()
    : trimmed.slice(opened + 1).trim();
}

// What the contract makes of one answer: the payload to store, or the
// sentences saying why there is none. Never both.
//
// A field the answer states nothing for is absent or null, and the two
// are one state here rather than two. That is the null-vs-zero rule
// read at this boundary, the same way ContractField.required reads it
// in src/lib/parser-config.ts: a field answered as 0 or as the empty
// string was answered, and a required field answered as null was not.
//
// A field the contract names and the answer got the shape of wrong
// refuses the whole answer, required or not. The contract declared a
// type for it either way, so a wrong shape is a wrong answer rather
// than a missing one, and dropping the member quietly would store a
// finding that reads as complete.
//
// A member the contract does not name never reaches the payload. The
// keys written are the contract's own, so an answer that invented a
// field loses it: what a domain's findings hold is the domain's
// declaration and not a model's.
function readAnswer(answer, contract) {
  const carried = answerText(answer);

  if (carried.fault !== '') {
    return { fields: null, faults: [carried.fault] };
  }

  let parsed = null;

  try {
    parsed = JSON.parse(unfenced(carried.text));
  } catch {
    return { fields: null, faults: [ANSWER_FAULTS.notJson] };
  }

  if (parsed === null || typeof parsed !== 'object'
    || Array.isArray(parsed)) {
    return { fields: null, faults: [ANSWER_FAULTS.notObject] };
  }

  const fields = {};
  const faults = [];

  for (const field of contract) {
    const site = 'field ' + field.name + ' ';
    const value = ownValue(parsed, field.name);

    if (value === undefined || value === null) {
      if (field.required) {
        faults.push(site + 'is required and the answer states none');
      }

      continue;
    }

    if (!isShape(value, field.type)) {
      faults.push(site + 'is not the declared type: ' + field.type);
      continue;
    }

    fields[field.name] = value;
  }

  return faults.length === 0
    ? { fields, faults }
    : { fields: null, faults };
}

// The domain row, which Load Domain Context answers as null for a run
// id that resolved to nothing. Reading the contract off a null is a
// fault of the pass rather than of an answer, so it stops here with the
// rest of them.
const domain = $('Load Domain Context').first().json.domain;

if (domain === null || domain === undefined) {
  throw new Error(
    '[ar-ingest] Validate Finding Fields has no domain row: the run this '
    + 'pass was started with resolves to none',
  );
}

const settings = domain.settings;
const contract = contractFields(
  settings !== null && typeof settings === 'object'
    ? ownValue(settings, 'fieldContract')
    : undefined,
);
const ledger = $input.all();
const answers = $('Extract Finding Fields').all();

// Held against each other before either is read. Both lists are one
// item per call by construction, the ledger statement answering one row
// whatever it wrote and the chain node answering one item whatever came
// back, so a length that differs is a canvas that has stopped meaning
// what this node reads it to mean. Going on would file one document's
// answer under another document, which no later node undoes and none
// reports.
if (ledger.length !== answers.length) {
  throw new Error(
    '[ar-ingest] Validate Finding Fields cannot pair '
    + String(ledger.length) + ' ledger rows against '
    + String(answers.length) + ' answers: the two are paired by position '
    + 'and a difference between them files an answer under the wrong '
    + 'document',
  );
}

// What each item carries onward. The ids it arrived with, so the
// statement below writes against the same document the call was made
// about, and the two members that are this node's answer. Exactly one
// of them is ever set: a payload and no reason, or a reason and no
// payload.
return ledger.map((item, index) => {
  const row = item.json;
  const read = readAnswer(answers[index].json, contract);

  return {
    json: {
      run_id: row.run_id,
      domain_id: row.domain_id,
      source_id: row.source_id,
      document_id: row.document_id,
      llm_call_id: row.llm_call_id,
      finding_fields: read.fields,
      finding_refusal: read.fields === null
        ? read.faults.join(REFUSAL_JOIN)
        : null,
    },
  };
});

